{
  "reviewer": "Reviewer - No Persona",
  "decision": "Accept",
  "scores": {
    "novelty": 5,
    "soundness": 4,
    "significance": 5,
    "evaluation": 4,
    "clarity": 4
  },
  "strengths": [
    "Introduces a novel concept (In-Run Data Shapley) that eliminates the need for computationally expensive model retraining required by traditional Data Shapley methods",
    "Develops highly efficient 'ghost' techniques for computing gradient dot-products and gradient-Hessian-gradient products with minimal runtime overhead compared to standard training",
    "Provides compelling case studies demonstrating practical applications in data curation, training dynamics analysis, and copyright implications for generative AI"
  },
  "weaknesses": [
    "Limited empirical validation on very large-scale models; experiments focus on GPT2 and Pythia-410M rather than true foundation models",
    "The approximation quality of Taylor expansions for utility functions is not thoroughly analyzed across different model architectures and optimization settings",
    "Requires validation data to be available before training, which may limit applicability in some real-world scenarios"
  ],
  "weakness_details": [
    {
      "weakness": "Limited empirical validation on very large-scale models; experiments focus on GPT2 and Pythia-410M rather than true foundation models",
      "severity": "minor",
      "evidence": "The paper states 'due to computational resource constraints, most of our experiments focus on the GPT-2 and Pythia-410M models' and acknowledges this is not a limitation of the algorithm itself",
      "affected_claim": "Claim that the method scales to foundation model pretraining",
      "fixable_without_substantial_new_work": true
    },
    {
      "weakness": "The approximation quality of Taylor expansions for utility functions is not thoroughly analyzed across different model architectures and optimization settings",
      "severity": "minor",
      "evidence": "While Section E.2.1 shows approximation errors for different learning rates, the analysis is limited to GPT2 and doesn't comprehensively address how approximation quality varies across architectures or optimization methods",
      "affected_claim": "General applicability of the Taylor approximation approach",
      "fixable_without_substantial_new_work": false
    }
  ],
  "acceptance_gates": {
    "soundness": {
      "result": "pass",
      "justification": "The theoretical foundations are solid, with proper derivations of closed-form Shapley values for Taylor approximations. The efficiency techniques are technically sound and well-explained."
    },
    "novelty": {
      "result": "pass",
      "justification": "The concept of In-Run Data Shapley is fundamentally novel, addressing both computational and conceptual limitations of retraining-based approaches. The 'ghost' techniques for efficient computation represent significant technical innovation."
    },
    "significance": {
      "result": "pass",
      "justification": "This work enables data attribution at scales previously impossible, with direct implications for data curation, copyright analysis, and understanding training dynamics. The efficiency gains are dramatic (negligible overhead for first-order version)."
    },
    "evaluation": {
      "result": "pass",
      "justification": "Comprehensive evaluation includes runtime analysis, approximation fidelity, and multiple case studies. The experiments demonstrate practical utility in data curation, training dynamics analysis, and copyright-relevant scenarios."
    },
    "presentation": {
      "result": "pass",
      "justification": "The paper is well-structured with clear explanations of concepts, technical details, and experimental results. The writing is generally clear despite the complex technical content."
    }
  },
  "summary_comment": "This paper makes a significant contribution by introducing In-Run Data Shapley, which eliminates the computational burden of traditional retraining-based Data Shapley methods. The technical innovations in efficient computation are impressive, achieving near-zero overhead for first-order approximations. The work is novel, sound, and highly significant for enabling data attribution at foundation model scale. While empirical validation on larger models would strengthen the claims, the current results on GPT2 and Pythia-410M are compelling. The case studies provide valuable insights into data curation, training dynamics, and copyright implications. This represents a substantial advance in data attribution methodology with practical applications in real-world ML systems."
}

